draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var parts = [
  { name: "F  (1 x 1.0%)", v: 1.0 },
  { name: "L  (1 x 0.5%)", v: 0.5 },
  { name: "d  (2 x 1.5%)", v: 3.0 },
  { name: "e  (1 x 3.0%)", v: 3.0 }
];
var i, sq = 0;
for (i = 0; i < parts.length; i++) sq += parts[i].v * parts[i].v;
var total = Math.sqrt(sq);

var left = 110;
var barW = W - left - 70;
var top = 26;
var rowH = (H - top - 52) / 5;
var scale = barW / 5.0;

ctx.fillStyle = C.ink;
ctx.fillText("Error budget for Y = 4FL / (pi d^2 e)", 12, 16);

for (i = 0; i < parts.length; i++) {
  var y = top + rowH * i + 14;
  ctx.fillStyle = C.figure;
  ctx.fillText(parts[i].name, 12, y + 4);
  ctx.fillStyle = C.rule;
  ctx.fillRect(left, y - 8, parts[i].v * scale, 13);
  ctx.fillStyle = C.figure;
  ctx.fillText(parts[i].v.toFixed(1) + "%", left + parts[i].v * scale + 6, y + 4);
}

var yt = top + rowH * 4 + 20;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(12, yt - 12); ctx.lineTo(W - 12, yt - 12); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("total (quadrature)", 12, yt + 6);
ctx.fillStyle = C.accent;
ctx.fillRect(left, yt - 6, total * scale, 13);
ctx.fillStyle = C.ink;
ctx.fillText(total.toFixed(2) + "%", left + total * scale + 6, yt + 6);

ctx.fillStyle = C.figure;
ctx.fillText("The total is smaller than the plain sum, 7.5%. Only the two biggest terms matter.", 12, H - 10);

out.note = "d and e together supply " + ((9 + 9) / sq * 100).toFixed(0) + " percent of the variance";
